/// Cette règle du « taux effectif » s'applique notamment et sous certaines conditions :
/// - aux salariés détachés à l'étranger
/// - aux fonctionnaires des organisations internationales
/// - aux contribuables soumis au régime micro-entreprise
#[allow(dead_code, unused_variables)]
pub fn calculate_taux_effectif(
    parameters: &Parameters,
    period: NaiveDate,
    profile: &Profile,
) -> f64 {
    let rni = calculate_rni(parameters, period, profile);
    let nbptr = calculate_nbptr(parameters, period, profile);
    let microentreprise = calculate_microentreprise(parameters, period, profile);
    let abnc_proc_i = calculate_abnc_proc(parameters, period, profile);
    let bareme = parameters.get_brackets("impot_revenu/bareme_ir_depuis_1945/bareme").unwrap_or_default();
    let abnc_proc = abnc_proc_i;
    let base_fictive = rni + microentreprise + abnc_proc;
    // UNTRANSLATED: trigger = (microentreprise != 0) | (abnc_proc != 0)
    return trigger * nbptr * bareme.calc(base_fictive / nbptr) / (1).max(base_fictive);
    0.0_f64
}

#[allow(dead_code, unused_variables)]
