#[allow(dead_code, unused_variables)]
pub fn calculate_decote(
    parameters: &Parameters,
    period: NaiveDate,
    profile: &Profile,
) -> f64 {
    let ir_plaf_qf = calculate_ir_plaf_qf(parameters, period, profile);
    let nb_adult = calculate_nb_adult(parameters, period, profile);
    let taux_decote = parameters.get_scalar("impot_revenu/calcul_impot_revenu/plaf_qf/decote/taux").unwrap_or(0.0);
    let decote_seuil_celib = parameters.get_scalar("impot_revenu/calcul_impot_revenu/plaf_qf/decote/seuil_celib").unwrap_or(0.0);
    let decote_seuil_couple = parameters.get_scalar("impot_revenu/calcul_impot_revenu/plaf_qf/decote/seuil_couple").unwrap_or(0.0);
    let decote_celib = (0.0_f64).max(decote_seuil_celib - taux_decote * ir_plaf_qf);
    let decote_couple = (0.0_f64).max(decote_seuil_couple - taux_decote * ir_plaf_qf);

    return ((if (nb_adult) == (1) { 100.0_f64 } else { 0.0_f64 }).round() / 100.0_f64 * decote_celib + if (nb_adult) == (2) { decote_couple } else { 0.0_f64 });
}

