#[allow(dead_code, unused_variables)]
pub fn calculate_reduction_impot_exceptionnelle(
    parameters: &Parameters,
    period: NaiveDate,
    profile: &Profile,
) -> f64 {
    let nb_adult = calculate_nb_adult(parameters, period, profile);
    let nbptr = calculate_nbptr(parameters, period, profile);
    let rfr = calculate_rfr(parameters, period, profile);
    let params = parameters.get_scalar("impot_revenu/calcul_reductions_impots/reduction_impot_exceptionnelle").unwrap_or(0.0);
    let plafond = params.seuil * nb_adult + (nbptr - nb_adult) * 2 * params.majoration_seuil;
    let montant = params.montant_plafond * nb_adult;
    return ((plafond + montant - rfr).max(0)).min(montant);
}

